static juce::Image loadB64Image (const char* const* chunks)
{
    juce::String all;
    for (int i = 0; chunks[i] != nullptr; ++i)
        all += juce::String (chunks[i]);

    juce::MemoryOutputStream out;
    if (! juce::Base64::convertFromBase64 (out, all))
        return {};
    return juce::ImageFileFormat::loadFrom (out.getData(), out.getDataSize());
}

